  ctx.beginPath();
  ctx.moveTo(405, 88); ctx.lineTo(405, 190);
  ctx.moveTo(419, 88); ctx.lineTo(419, 190);
  ctx.stroke();

  // Vòng dây sục xoắn lò xo phát nhiệt đỏ cam sắc nét
  const pulse = 0.78 + 0.22 * Math.sin(t * 7);
