  ctx.lineWidth = 3.6;
  for (let i = 0; i < 6; i++) {
    const cy = 194 + i * 8;
    ctx.beginPath();
    ctx.ellipse(412, cy, 18, 4.5, 0, 0, Math.PI * 2);
