    const p = ((t * (0.45 + (i % 4) * 0.12) + i * 0.19) % 1);
    const bx = 385 + ((i * 19) % 54) + Math.sin(p * 8 + i) * 3;
    const by = 236 - p * (236 - waterTopY - 4);
    const br = 1.8 + p * 2.5 * (0.4 + 0.6 * cycle);
