    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.arc(bx, by, br, 0, Math.PI * 2);
    ctx.stroke();
  }

  // Hơi nước bốc lên mặt thoáng khi nhiệt độ cao
  if (cycle > 0.35) {
